/**
 * The compatibility matrix's shape and its loader (JAN-TOOLCUR D-7; roadmap T0).
 *
 * THREE KINDS OF FIELD, AND WHO MAY CHANGE EACH (D-7, I7).
 * - GENERATED by `generate.ts`: a package's declared ranges, its lock-resolved version and its nested copies, and the
 *   day-to-day Node, read from `.node-version`. Regenerating them is an ordinary re-baseline.
 * - OBSERVED from the machine: the Edge major, the SonarLint version and the host tools' versions, each with its
 *   date. When `toolchain:check` reports drift, whoever ran it records the new value; that is an ordinary re-baseline.
 * - HAND-WRITTEN judgments: coupling group, floor, pin style, blockers, the instruments a component moves, the
 *   runtime each gate step runs on, and the reason for each. `toolchain:check` enforces them, so they are gate
 *   configuration: weakening, rewriting or removing one is a separately authorized act (I7).
 *
 * The loader refuses a matrix it cannot use and says what is missing. That refusal is condition 8 of D-9: an empty or
 * unreadable matrix must fail, because a check over no rows compares nothing and would pass (I6).
 */

export type PinStyle = 'exact' | 'caret';
export type StepRuntime = 'node' | 'bun' | 'node+bun' | 'none';
export type MachineCheck = 'major' | 'version' | 'none';

export interface Judgment {
	readonly group: string;
	readonly blockers: readonly string[];
	readonly moves: readonly string[];
}

export interface NodeRow extends Judgment {
	/** Hand-written: the oldest Node JPWB promises to run on, as `engines.node` writes it after `>=`. */
	readonly floor: string;
	readonly floorReason: string;
	/** Generated from `.node-version`. */
	readonly dayToDay: string;
	readonly supportWindow: string;
	/** Observed: versions built into the Node this matrix records. */
	readonly bundled: Readonly<Record<string, string>>;
}

export interface BunRow extends Judgment {
	/** Hand-written exact pin (D-8): Bun reads none of `packageManager`, `engines` or `devEngines`, so this check does. */
	readonly version: string;
	readonly reason: string;
}

export interface PackageRow extends Judgment {
	readonly component: string;
	readonly pin: PinStyle;
	readonly reason: string;
	/** Generated: manifest directory ('.' for the root) -> the range it declares. */
	readonly declared: Readonly<Record<string, string>>;
	/** Generated: the hoisted copy's version in `bun.lock`. */
	readonly locked: string;
	/** Generated: each nested copy's lock key -> its version. */
	readonly nested: Readonly<Record<string, string>>;
}

export interface MachineRow {
	readonly component: string;
	readonly group: string;
	/** Hand-written: what `toolchain:check` compares (condition 7), or 'none' for a recorded-only tool. */
	readonly check: MachineCheck;
	/** Observed: the value the check compares, or the recorded version of a recorded-only tool. */
	readonly observed: string;
	readonly date: string;
	readonly detail: string;
	/** For a recorded-only tool: the `executables` entry in `machine-paths.json` that reads its version. */
	readonly probe?: string;
}

export interface VsCodeRow {
	readonly group: string;
	/** Hand-written: the planned extension's floor (D-2), and the chain at that floor (F-5's `.npmrc` table). */
	readonly floor: string;
	readonly floorElectron: string;
	readonly floorNode: string;
	readonly floorChromium: string;
	readonly source: string;
	/** Observed installs: product, version, the Node its extension host runs ('' when not measured). */
	readonly observed: readonly { readonly product: string; readonly version: string; readonly node: string; readonly date: string }[];
}

export interface Matrix {
	readonly schema: string;
	readonly node: NodeRow;
	readonly bun: BunRow;
	readonly packages: readonly PackageRow[];
	readonly machine: readonly MachineRow[];
	readonly vscode: VsCodeRow;
	/** Hand-written: the declared browser floor (D-6), `null` until T1c sets it. */
	readonly browserFloor: string | null;
	/** Hand-written: the runtime each `gate:fast` step runs on (D-9; F-3). */
	readonly gateSteps: Readonly<Record<string, StepRuntime>>;
}

export const MATRIX_SCHEMA = 'jpwb-toolchain-matrix/1';

const STEP_RUNTIMES: ReadonlySet<string> = new Set(['node', 'bun', 'node+bun', 'none']);
const MACHINE_CHECKS: ReadonlySet<string> = new Set(['major', 'version', 'none']);

function isRecord(v: unknown): v is Record<string, unknown> {
	return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function isStringRecord(v: unknown): v is Record<string, string> {
	return isRecord(v) && Object.values(v).every((x) => typeof x === 'string');
}

function isStringList(v: unknown): v is string[] {
	return Array.isArray(v) && v.every((x) => typeof x === 'string');
}

function isText(v: unknown): v is string {
	return typeof v === 'string' && v !== '';
}

/** The three hand-written judgment fields every runtime and package row carries. */
function judgmentProblems(where: string, row: Record<string, unknown>): string[] {
	const problems: string[] = [];
	if (!isText(row.group)) problems.push(`${where}: no coupling group`);
	if (!isStringList(row.blockers)) problems.push(`${where}: blockers is not a list of strings`);
	if (!isStringList(row.moves)) problems.push(`${where}: moves is not a list of strings`);
	return problems;
}

function nodeProblems(node: unknown): string[] {
	if (!isRecord(node)) return ['no node row'];
	const problems = judgmentProblems('node', node);
	for (const f of ['floor', 'floorReason', 'dayToDay', 'supportWindow']) {
		if (!isText(node[f])) problems.push(`node: no ${f}`);
	}
	if (!isStringRecord(node.bundled)) problems.push('node: bundled is not an object of strings');
	return problems;
}

function bunProblems(bun: unknown): string[] {
	if (!isRecord(bun)) return ['no bun row'];
	const problems = judgmentProblems('bun', bun);
	if (!isText(bun.version)) problems.push('bun: no version');
	if (!isText(bun.reason)) problems.push('bun: no reason');
	return problems;
}

function packageRowProblems(p: Record<string, unknown>, where: string): string[] {
	const problems = judgmentProblems(where, p);
	if (p.pin !== 'exact' && p.pin !== 'caret') problems.push(`${where}: pin is ${JSON.stringify(p.pin)}`);
	if (!isText(p.reason)) problems.push(`${where}: no reason`);
	if (!isStringRecord(p.declared) || Object.keys(p.declared).length === 0) problems.push(`${where}: declared names no manifest`);
	if (!isText(p.locked)) problems.push(`${where}: no locked version`);
	if (!isStringRecord(p.nested)) problems.push(`${where}: nested is not an object of strings`);
	return problems;
}

function packagesProblems(packages: unknown): string[] {
	if (!Array.isArray(packages) || packages.length === 0) return ['packages is empty or missing'];
	const problems: string[] = [];
	const seen = new Set<string>();
	packages.forEach((p: unknown, i: number) => {
		if (!isRecord(p) || !isText(p.component)) {
			problems.push(`packages[${i}]: no component name`);
			return;
		}
		const where = `package ${p.component}`;
		if (seen.has(p.component)) problems.push(`${where}: listed twice`);
		seen.add(p.component);
		problems.push(...packageRowProblems(p, where));
	});
	return problems;
}

function machineRowProblems(m: Record<string, unknown>, where: string): string[] {
	const problems: string[] = [];
	if (!isText(m.group)) problems.push(`${where}: no coupling group`);
	if (typeof m.check !== 'string' || !MACHINE_CHECKS.has(m.check)) problems.push(`${where}: check is ${JSON.stringify(m.check)}`);
	for (const f of ['observed', 'date', 'detail']) {
		if (typeof m[f] !== 'string') problems.push(`${where}: no ${f}`);
	}
	if (m.probe !== undefined && typeof m.probe !== 'string') problems.push(`${where}: probe is not a string`);
	return problems;
}

function machineProblems(machine: unknown): string[] {
	if (!Array.isArray(machine) || machine.length === 0) return ['machine is empty or missing'];
	const problems: string[] = [];
	machine.forEach((m: unknown, i: number) => {
		if (!isRecord(m) || !isText(m.component)) problems.push(`machine[${i}]: no component name`);
		else problems.push(...machineRowProblems(m, `machine ${m.component}`));
	});
	return problems;
}

function vscodeProblems(vscode: unknown): string[] {
	if (!isRecord(vscode)) return ['no vscode row'];
	const problems: string[] = [];
	for (const f of ['group', 'floor', 'floorElectron', 'floorNode', 'floorChromium', 'source']) {
		if (!isText(vscode[f])) problems.push(`vscode: no ${f}`);
	}
	if (!Array.isArray(vscode.observed)) problems.push('vscode: observed is not a list');
	return problems;
}

function gateStepProblems(gateSteps: unknown): string[] {
	if (!isRecord(gateSteps) || Object.keys(gateSteps).length === 0) return ['gateSteps is empty or missing'];
	return Object.entries(gateSteps)
		.filter(([, runtime]) => typeof runtime !== 'string' || !STEP_RUNTIMES.has(runtime))
		.map(([step, runtime]) => `gateSteps: "${step}" records ${JSON.stringify(runtime)}`);
}

/** Every reason the parsed value is not a usable matrix; empty when it is one. */
export function matrixProblems(raw: unknown): string[] {
	if (!isRecord(raw)) return ['the matrix is not a JSON object'];
	const problems: string[] = [];
	if (raw.schema !== MATRIX_SCHEMA) problems.push(`schema is ${JSON.stringify(raw.schema)}, not "${MATRIX_SCHEMA}"`);
	if (raw.browserFloor !== null && typeof raw.browserFloor !== 'string') problems.push('browserFloor is neither null nor a string');
	return [
		...problems,
		...nodeProblems(raw.node),
		...bunProblems(raw.bun),
		...packagesProblems(raw.packages),
		...machineProblems(raw.machine),
		...vscodeProblems(raw.vscode),
		...gateStepProblems(raw.gateSteps)
	];
}

/** Parse matrix text, or throw with every problem found. */
export function parseMatrix(text: string): Matrix {
	let raw: unknown;
	try {
		raw = JSON.parse(text);
	} catch (e) {
		throw new Error(`the matrix is not JSON: ${(e as Error).message}`);
	}
	const problems = matrixProblems(raw);
	if (problems.length > 0) throw new Error(`the matrix is not usable: ${problems.join('; ')}`);
	return raw as Matrix;
}

/** Numeric parts of a version, `v24.22.3` or `24.22.3` -> [24, 22, 3]; a partial floor `22` -> [22]. */
export function versionParts(version: string): number[] {
	const m = /^v?(\d+(?:\.\d+)*)/.exec(version.trim());
	if (m === null) throw new Error(`not a version: ${JSON.stringify(version)}`);
	return (m[1] ?? '').split('.').map(Number);
}

/** Compare two versions part by part, missing parts read as 0: negative, zero or positive. */
export function compareVersions(a: string, b: string): number {
	const pa = versionParts(a);
	const pb = versionParts(b);
	for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
		const d = (pa[i] ?? 0) - (pb[i] ?? 0);
		if (d !== 0) return d;
	}
	return 0;
}
